using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Linq;using Abyss.Story;
namespace Abyss.EditorTools {
[InitializeOnLoad] public static class Revision13Setup {
 static Revision13Setup(){EditorApplication.playModeStateChanged+=state=>{if(state==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("R13",false)){SessionState.SetBool("R13",false);Application.runInBackground=true;Camera.main.gameObject.AddComponent<Revision13Verification>();}};EditorApplication.update+=()=>{var p="Temp/revision13-command.txt";if(!File.Exists(p)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;var cmd=File.ReadAllText(p).Trim();File.Delete(p);if(cmd=="apply")Apply();if(cmd=="verify"){Application.runInBackground=true;SessionState.SetBool("R13",true);EditorApplication.isPlaying=true;}};}
 static Sprite S(string n)=>AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Underwater/Resources/Abyss/"+n+".png");
 static void Apply(){if(EditorApplication.isPlaying)return;var story=Object.FindFirstObjectByType<UnderwaterDayStory>();if(story.gameObject.scene.path!="Assets/Scenes/UnderwaterWorld.unity")return;foreach(var p in Directory.GetFiles("Assets/Underwater/Resources/Abyss","*.png").Where(p=>Path.GetFileName(p).StartsWith("heart_")||Path.GetFileName(p).StartsWith("brine_"))){var imp=(TextureImporter)AssetImporter.GetAtPath(p);imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.alphaIsTransparency=true;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.spritePixelsPerUnit=64;if(Path.GetFileName(p).StartsWith("brine_")){var set=new TextureImporterSettings();imp.ReadTextureSettings(set);set.spriteAlignment=(int)SpriteAlignment.Custom;set.spritePivot=new Vector2(.5f,1);imp.SetTextureSettings(set);}imp.SaveAndReimport();}
 var env=story.GetComponent<WarEnvironment>();env.canFrequencyMultiplier=2.25f;var brine=env.GetComponent<BrineDischarge>()??env.gameObject.AddComponent<BrineDischarge>();brine.environment=env;brine.outletOffset=new Vector2(-8.2f,-2.4f);brine.frames=Enumerable.Range(0,4).Select(i=>S("brine_"+i)).ToArray();story.ui.fullHeart=S("heart_0");story.ui.emptyHeart=S("heart_2");
 story.thirdChapter.hazards.sections=new[]{new CannonSection{left=-145,right=-86},new CannonSection{left=-74,right=-6},new CannonSection{left=6,right=69},new CannonSection{left=81,right=145}};var audio=story.GetComponent<UnderwaterSceneAudio>();audio.ambienceVolume=.3f;audio.bubbleVolume=.11f;
 if(!File.Exists("Tools/Revision13/mayor-moved.txt")){story.mayor.transform.position+=Vector3.right*1.2f;File.WriteAllText("Tools/Revision13/mayor-moved.txt","Initial mayor +1.2 world X only");}
 EditorSceneManager.MarkSceneDirty(story.gameObject.scene);EditorSceneManager.SaveScene(story.gameObject.scene);File.WriteAllText("Tools/Revision13/setup.txt","Brine/heart sprites imported; initial mayor moved 1.2 right; ambience gain 0.3, bubbles 0.11. No suitable distant cannon recording found.");}
}}
